            "task:state_changed" -> json.decodeFromJsonElement(TaskStateChangedEvent.serializer(), element)
            "task:log" -> json.decodeFromJsonElement(TaskLogEvent.serializer(), element)
            "task:created" -> json.decodeFromJsonElement(TaskCreatedEvent.serializer(), element)
            "task:pending_reason" -> json.decodeFromJsonElement(TaskPendingReasonEvent.serializer(), element)
            "task:stalled" -> json.decodeFromJsonElement(TaskStalledEvent.serializer(), element)
            "task:recovered" -> json.decodeFromJsonElement(TaskRecoveredEvent.serializer(), element)
            "auth:failed" -> json.decodeFromJsonElement(AuthFailedEvent.serializer(), element)
            "auth:status_changed" -> json.decodeFromJsonElement(AuthStatusChangedEvent.serializer(), element)
            "session:created" -> json.decodeFromJsonElement(SessionCreatedEvent.serializer(), element)
            "session:ended" -> json.decodeFromJsonElement(SessionEndedEvent.serializer(), element)
            "task:comment" -> json.decodeFromJsonElement(TaskCommentEvent.serializer(), element)
            "task:message" -> json.decodeFromJsonElement(TaskMessageEvent.serializer(), element)
            "task:message_delivered", "task:message_acked" -> json.decodeFromJsonElement(TaskMessageDeliveredEvent.serializer(), element)
            "workflow_run:state_changed" -> json.decodeFromJsonElement(WorkflowRunStateChangedEvent.serializer(), element)
            "workflow_run:log" -> json.decodeFromJsonElement(WorkflowRunLogEvent.serializer(), element)
            "pr_review:state_changed" -> json.decodeFromJsonElement(PrReviewStateChangedEvent.serializer(), element)
            "pr_review_run:state_changed" -> json.decodeFromJsonElement(PrReviewRunStateChangedEvent.serializer(), element)
            "pr_review_run:log" -> json.decodeFromJsonElement(PrReviewRunLogEvent.serializer(), element)
            "pr_review:stale" -> json.decodeFromJsonElement(PrReviewStaleEvent.serializer(), element)
            "activity:new" -> json.decodeFromJsonElement(ActivityNewEvent.serializer(), element)
            "persistent_agent:state_changed" -> json.decodeFromJsonElement(PersistentAgentStateChangedEvent.serializer(), element)
            "persistent_agent:turn_started" -> json.decodeFromJsonElement(PersistentAgentTurnStartedEvent.serializer(), element)
            "persistent_agent:turn_halted" -> json.decodeFromJsonElement(PersistentAgentTurnHaltedEvent.serializer(), element)
            "persistent_agent:message" -> json.decodeFromJsonElement(PersistentAgentMessageEvent.serializer(), element)
            "persistent_agent:log" -> json.decodeFromJsonElement(PersistentAgentLogEvent.serializer(), element)
            "local:changed" -> json.decodeFromJsonElement(LocalChangedEvent.serializer(), element)
            else -> null
        }

        override fun encode(value: WsEvent, json: Json): JsonElement = when (value) {
            is TaskStateChangedEvent -> json.encodeToJsonElement(TaskStateChangedEvent.serializer(), value)
            is TaskLogEvent -> json.encodeToJsonElement(TaskLogEvent.serializer(), value)
            is TaskCreatedEvent -> json.encodeToJsonElement(TaskCreatedEvent.serializer(), value)
            is TaskPendingReasonEvent -> json.encodeToJsonElement(TaskPendingReasonEvent.serializer(), value)
            is TaskStalledEvent -> json.encodeToJsonElement(TaskStalledEvent.serializer(), value)
            is TaskRecoveredEvent -> json.encodeToJsonElement(TaskRecoveredEvent.serializer(), value)
            is AuthFailedEvent -> json.encodeToJsonElement(AuthFailedEvent.serializer(), value)
            is AuthStatusChangedEvent -> json.encodeToJsonElement(AuthStatusChangedEvent.serializer(), value)
            is SessionCreatedEvent -> json.encodeToJsonElement(SessionCreatedEvent.serializer(), value)
            is SessionEndedEvent -> json.encodeToJsonElement(SessionEndedEvent.serializer(), value)
            is TaskCommentEvent -> json.encodeToJsonElement(TaskCommentEvent.serializer(), value)
            is TaskMessageEvent -> json.encodeToJsonElement(TaskMessageEvent.serializer(), value)
            is TaskMessageDeliveredEvent -> json.encodeToJsonElement(TaskMessageDeliveredEvent.serializer(), value)
            is WorkflowRunStateChangedEvent -> json.encodeToJsonElement(WorkflowRunStateChangedEvent.serializer(), value)
            is WorkflowRunLogEvent -> json.encodeToJsonElement(WorkflowRunLogEvent.serializer(), value)
            is PrReviewStateChangedEvent -> json.encodeToJsonElement(PrReviewStateChangedEvent.serializer(), value)
            is PrReviewRunStateChangedEvent -> json.encodeToJsonElement(PrReviewRunStateChangedEvent.serializer(), value)
            is PrReviewRunLogEvent -> json.encodeToJsonElement(PrReviewRunLogEvent.serializer(), value)
            is PrReviewStaleEvent -> json.encodeToJsonElement(PrReviewStaleEvent.serializer(), value)
            is ActivityNewEvent -> json.encodeToJsonElement(ActivityNewEvent.serializer(), value)
            is PersistentAgentStateChangedEvent -> json.encodeToJsonElement(PersistentAgentStateChangedEvent.serializer(), value)
            is PersistentAgentTurnStartedEvent -> json.encodeToJsonElement(PersistentAgentTurnStartedEvent.serializer(), value)
            is PersistentAgentTurnHaltedEvent -> json.encodeToJsonElement(PersistentAgentTurnHaltedEvent.serializer(), value)
            is PersistentAgentMessageEvent -> json.encodeToJsonElement(PersistentAgentMessageEvent.serializer(), value)
            is PersistentAgentLogEvent -> json.encodeToJsonElement(PersistentAgentLogEvent.serializer(), value)
            is LocalChangedEvent -> json.encodeToJsonElement(LocalChangedEvent.serializer(), value)
            is Unknown -> value.raw
        }

        override fun unknown(raw: JsonElement): WsEvent = Unknown(raw)
    }
}

