/** How the daemon should build the process for a terminal. */
@Serializable(with = LocalTerminalSpec.Serializer::class)
sealed interface LocalTerminalSpec {
    data object Shell : LocalTerminalSpec

    @Serializable
    data class Command(
        val command: String,
    ) : LocalTerminalSpec

    @Serializable
    data class Agent(
        val agent: LocalAgentKind,
        val prompt: String? = null,
        /** Default `interactive`. */
        val mode: LocalAgentSessionMode? = null,
        /**
         * Resume a previous agent session (its id as reported by the agent's
         * hooks) instead of starting a fresh one. Interactive unless the agent
         * supports a headless resume (Claude Code: `claude -p --resume`).
         */
        val resumeSessionId: String? = null,
        /** Model override passed to the agent CLI (`--model` / `-m`), when set. */
        val model: String? = null,
        /**
         * Reasoning effort passed to the agent CLI, when set: Claude Code
         * `--effort`, Codex `-c model_reasoning_effort=…`.
         */
        val effort: String? = null,
        /**
         * Claude Code: its `--permission-mode` (the daemon's default is `auto`).
         * Codex: `bypassPermissions` runs it with `--yolo`; anything else keeps
         * the machine's own config.
         */
        val permissionMode: LocalAgentPermissionMode? = null,
        /**
         * "Work on a new branch that becomes a PR": the server wraps the prompt
         * with branch-and-PR instructions off this base before the spawn.
         */
        val baseBranch: String? = null,
        /**
         * Reach the models through this provider (Amazon Bedrock) instead of
         * the CLI's own sign-in, with the machine's own AWS credentials. Only
         * sent to daemons whose hello set `modelProviders`.
         */
        val provider: ModelProviderLaunch? = null,
    ) : LocalTerminalSpec

    /** Fallback for discriminator values this client does not know about yet. */
    data class Unknown(val raw: JsonElement) : LocalTerminalSpec

    object Serializer : DiscriminatedUnionSerializer<LocalTerminalSpec>("dev.optio.core.model.LocalTerminalSpec", "kind") {
        override fun decode(tag: String, element: JsonObject, json: Json): LocalTerminalSpec? = when (tag) {
            "shell" -> Shell
            "command" -> json.decodeFromJsonElement(Command.serializer(), element.withoutDiscriminator())
            "agent" -> json.decodeFromJsonElement(Agent.serializer(), element.withoutDiscriminator())
            else -> null
        }

        override fun encode(value: LocalTerminalSpec, json: Json): JsonElement = when (value) {
            is Shell -> tagged("shell")
            is Command -> tagged("command", json.encodeToJsonElement(Command.serializer(), value))
            is Agent -> tagged("agent", json.encodeToJsonElement(Agent.serializer(), value))
            is Unknown -> value.raw
        }

        override fun unknown(raw: JsonElement): LocalTerminalSpec = Unknown(raw)
    }
}

