data class Workflow(
    val id: String,
    val name: String,
    val description: String? = null,
    val workspaceId: String? = null,
    val environmentSpec: Map<String, JsonElement>? = null,
    val promptTemplate: String,
    /** `{{param}}` template each run is named from; null = the workflow's name. */
    val runTitle: String? = null,
    val paramsSchema: Map<String, JsonElement>? = null,
    val agentRuntime: String,
    val model: String? = null,
    val maxTurns: Double? = null,
    val budgetUsd: String? = null,
    val maxConcurrent: Double,
    val maxRetries: Double,
    val warmPoolSize: Double,
    /** Where runs execute: an Optio pod (`cluster`, default) or the owner's machine (`local`). */
    val runTarget: RunTarget,
    val localHostId: String? = null,
    val localDir: String? = null,
    val localSessionMode: LocalAgentSessionMode? = null,
    val enabled: Boolean,
    val createdBy: String? = null,
    /**
     * Who the work belongs to: null = the organization; set = one person's own.
     * Personal work runs with that person's secrets, model providers and
     * connections, and only they can change it.
     */
    val ownerUserId: String? = null,
    /**
     * The secrets (by name) the agent gets in its pod. Null = the workspace's
     * legacy behavior (see `Workspace.restrictPodSecrets`).
     */
    val podSecrets: List<String>? = null,
    val createdAt: Instant,
    val updatedAt: Instant,
)

@Serializable
data class WorkflowTrigger(
    val id: String,
    val workflowId: String,
    val type: WorkflowTriggerType,
    val config: Map<String, JsonElement>? = null,
    val paramMapping: Map<String, JsonElement>? = null,
    val enabled: Boolean,
    val lastFiredAt: Instant? = null,
    val nextFireAt: Instant? = null,
    val createdAt: Instant,
    val updatedAt: Instant,
)

@Serializable
data class WorkflowRun(
    val id: String,
    val workflowId: String,
    val triggerId: String? = null,
    val params: Map<String, JsonElement>? = null,
    /** The workflow's runTitle rendered with this run's params; null = no template. */
    val title: String? = null,
    val state: WorkflowRunState,
    val output: Map<String, JsonElement>? = null,
    val costUsd: String? = null,
    val inputTokens: Double? = null,
    val outputTokens: Double? = null,
    val modelUsed: String? = null,
    val errorMessage: String? = null,
    val sessionId: String? = null,
    val podName: String? = null,
    /** Local runs: the `local_terminals` row executing this run. */
    val localTerminalId: String? = null,
    val retryCount: Double,
    val startedAt: Instant? = null,
    val finishedAt: Instant? = null,
    val createdAt: Instant,
    val updatedAt: Instant,
)

